designs.migrationSql:
-- FILE: supabase/migrations/20261111000000_closet_outfit_labels.sql
-- (sorts after 20261013000000_voice_notes.sql, the latest existing migration)

-- Per-closet outfit tags ("labels"). Until now the list of tags an outfit can
-- be given was a constant compiled into the app (OUTFIT_LABELS in
-- src/services/dataService.types.ts). This moves the list onto the closet so
-- its owner can add and remove tags under Settings > Edit tags.
--
-- Seeding and backfill are both the column default: it holds the same ten
-- generic tags the app shipped with, so every existing closet reads them the
-- moment the column is added, and every new closet starts with them because
-- neither the app's insert (supabaseClosetsService.createOwnCloset) nor
-- supabase/seed.sql names the column. Mirrored in
-- src/services/dataService.types.ts (DEFAULT_OUTFIT_LABELS,
-- MAX_OUTFIT_LABEL_LENGTH, MAX_OUTFIT_LABELS).
--
-- No new policies or table grants. "Members can view their closets" already
-- lets the closet's stylists read the list (they need it to tag the outfits
-- they create), and "Owners can update their closets" already limits
-- changing it to the owner.
--
-- The two functions exist because the client must not write the array
-- itself: a read-modify-write of the whole list from a phone that loaded it
-- yesterday would silently drop a tag added from another device since. Each
-- function changes one element in one locked step instead - same reasoning
-- as increment_outfit_compliment_count. No SECURITY DEFINER -- they run as
-- the caller, so the owner-only UPDATE policy still applies; the
-- is_closet_owner check is there to give a clear message instead of a
-- silent zero-row update.
--
-- outfits.labels is deliberately not touched. Removing a tag from a closet's
-- list leaves it on the outfits that already carry it: rewriting them would
-- fire log_outfit_activity_trigger and bump updated_at (the optimistic
-- concurrency token) on every one, for a change nobody made to those outfits.

ALTER TABLE "public"."closets"
    ADD COLUMN "outfit_labels" "text"[] DEFAULT ARRAY['Girly/Romantic'::"text", 'Work'::"text", 'Casual'::"text", 'Date Night'::"text", 'Athleisure'::"text", 'Formal Event'::"text", 'Street Style'::"text", 'Minimalist Chic'::"text", 'Artsy'::"text", 'Boho'::"text"] NOT NULL;

ALTER TABLE "public"."closets"
    ADD CONSTRAINT "closets_outfit_labels_count" CHECK ("cardinality"("outfit_labels") <= 50);


-- Appends one tag to a closet's list and returns the whole saved list.
CREATE OR REPLACE FUNCTION "public"."add_closet_outfit_label"("target_closet_id" "uuid", "target_label" "text") RETURNS "text"[]
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
declare
  v_label text := btrim(regexp_replace(coalesce(target_label, ''), '\s+', ' ', 'g'));
  v_labels text[];
  v_existing text;
begin
  if not public.is_closet_owner(target_closet_id) then
    raise exception 'Only the closet owner can edit tags';
  end if;

  if v_label = '' then
    raise exception 'Enter a tag name';
  end if;

  if char_length(v_label) > 30 then
    raise exception 'Tags can be up to 30 characters';
  end if;

  -- Row lock: a second add or remove for this closet waits here and then
  -- reads the list the first one wrote, so neither overwrites the other.
  select outfit_labels into v_labels
  from public.closets
  where id = target_closet_id
  for update;

  if not found then
    raise exception 'Only the closet owner can edit tags';
  end if;

  select existing.label into v_existing
  from unnest(v_labels) as existing(label)
  where lower(existing.label) = lower(v_label)
  limit 1;

  if v_existing is not null then
    raise exception 'You already have a tag called "%"', v_existing;
  end if;

  if cardinality(v_labels) >= 50 then
    raise exception 'You can have up to 50 tags';
  end if;

  update public.closets
  set outfit_labels = array_append(outfit_labels, v_label)
  where id = target_closet_id
  returning outfit_labels into v_labels;

  return v_labels;
end;
$$;


ALTER FUNCTION "public"."add_closet_outfit_label"("target_closet_id" "uuid", "target_label" "text") OWNER TO "postgres";


-- Removes one tag (exact match) from a closet's list and returns the whole
-- saved list. Removing a tag that is already gone is not an error, so a
-- second device working from an older list still succeeds.
CREATE OR REPLACE FUNCTION "public"."remove_closet_outfit_label"("target_closet_id" "uuid", "target_label" "text") RETURNS "text"[]
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
declare
  v_labels text[];
begin
  if not public.is_closet_owner(target_closet_id) then
    raise exception 'Only the closet owner can edit tags';
  end if;

  update public.closets
  set outfit_labels = array_remove(outfit_labels, target_label)
  where id = target_closet_id
  returning outfit_labels into v_labels;

  if v_labels is null then
    raise exception 'Only the closet owner can edit tags';
  end if;

  return v_labels;
end;
$$;


ALTER FUNCTION "public"."remove_closet_outfit_label"("target_closet_id" "uuid", "target_label" "text") OWNER TO "postgres";


GRANT ALL ON FUNCTION "public"."add_closet_outfit_label"("target_closet_id" "uuid", "target_label" "text") TO "anon";
GRANT ALL ON FUNCTION "public"."add_closet_outfit_label"("target_closet_id" "uuid", "target_label" "text") TO "authenticated";
GRANT ALL ON FUNCTION "public"."add_closet_outfit_label"("target_closet_id" "uuid", "target_label" "text") TO "service_role";

GRANT ALL ON FUNCTION "public"."remove_closet_outfit_label"("target_closet_id" "uuid", "target_label" "text") TO "anon";
GRANT ALL ON FUNCTION "public"."remove_closet_outfit_label"("target_closet_id" "uuid", "target_label" "text") TO "authenticated";
GRANT ALL ON FUNCTION "public"."remove_closet_outfit_label"("target_closet_id" "uuid", "target_label" "text") TO "service_role";

-- NOTES FOR THE IMPLEMENTER (not part of the file):
-- * Nothing here was executed; it is correct by inspection against the baseline (closets :114-120, policies :387/:403, grants :664-666, is_closet_owner :85-93) and the conventions of 20260722025112 (invoker RPC) and 20261013000000 (header, quoting, three grants).
-- * Two separate ALTER TABLE statements on purpose, so the CHECK never depends on same-statement ordering with ADD COLUMN.
-- * The column needs no GRANT (table-level GRANT ALL already covers it). The functions need the explicit grants: supabase/config.toml:19-24 says new entities are not auto-exposed.
-- * anon can EXECUTE (repo convention) but is_closet_owner is false without auth.uid(), so it always raises.
-- * A stylist calling either function raises 'Only the closet owner can edit tags' (is_closet_owner false); even without that check the UPDATE policy would match zero rows.
-- * ROLLOUT ORDER IS MANDATORY: apply this migration BEFORE deploying the new client. It is purely additive and safe for the currently deployed web app and old native builds (they never name the column). The new client selects outfit_labels in every closet query, so shipping it first makes closet loading fail for everyone.
-- * supabase/seed.sql and supabase/schema.sql (stale snapshot) are intentionally not edited.

