## 1. src/services/dataService.types.ts

Replace lines 210-228 (OUTFIT_LABELS const + OutfitLabel type) with:

```ts
/**
 * The generic outfit tags every closet starts with. Since closets got their
 * own editable list (closets.outfit_labels) this is only the starting point:
 * it mirrors that column's default in
 * supabase/migrations/20261111000000_closet_outfit_labels.sql and seeds the
 * guest closet in previewService.
 */
export const DEFAULT_OUTFIT_LABELS: readonly string[] = [
  'Girly/Romantic', 'Work', 'Casual', 'Date Night', 'Athleisure',
  'Formal Event', 'Street Style', 'Minimalist Chic', 'Artsy', 'Boho',
];

/** Longest tag a closet owner can add - also enforced by the add_closet_outfit_label RPC. */
export const MAX_OUTFIT_LABEL_LENGTH = 30;

/** Most tags one closet can hold - also enforced by the closets_outfit_labels_count check constraint. */
export const MAX_OUTFIT_LABELS = 50;

/** How a typed tag is stored: trimmed, with any run of whitespace collapsed to one space. */
export function normalizeOutfitLabel(value: string): string {
  return value.trim().replace(/\s+/g, ' ');
}
```

