```tsx
import { Stack } from 'expo-router';
import { useTheme } from '@/context/ThemeContext';

export const unstable_settings = {
  initialRouteName: 'index',
};

/**
 * Settings is a stack so Logs and Edit tags can be pushed on top of it with a
 * back button, the same way /closet/new sits on the Closet tab. Unlike the
 * closet and outfits stacks the header never takes the stylist colours:
 * Settings is about the signed-in account, and white on the stylist blue is
 * too low-contrast for the titles the web route announcer focuses.
 */
export default function SettingsLayout() {
  const { theme } = useTheme();

  return (
    <Stack
      screenOptions={{
        headerTitleAlign: 'center',
        headerStyle: { backgroundColor: theme.surface },
        headerTintColor: theme.textPrimary,
      }}
    />
  );
}
```
No headerLeft anywhere: sub-screens use the default back control, like closet/new.tsx.

