import { useToast } from '@/components/Toast';
import { useCloset } from '@/context/ClosetContext';
import { useTheme } from '@/context/ThemeContext';
import { getErrorMessage, MAX_OUTFIT_LABEL_LENGTH } from '@/services/dataService.types';
import { showAlert } from '@/utils/alert';
import { Stack } from 'expo-router';
import { useEffect, useRef, useState } from 'react';
import {
  AccessibilityInfo,
  ActivityIndicator,
  Platform,
  Pressable,
  ScrollView,
  StyleSheet,
  Text,
  TextInput,
  View,
} from 'react-native';

/**
 * Puts focus on `node`: keyboard focus on web (which screen readers follow),
 * the VoiceOver/TalkBack cursor on native. The two need different calls -
 * react-native-web has no sendAccessibilityEvent at all, and a native ref has
 * no focus() that moves the screen-reader cursor.
 */
function moveFocusTo(node: View | Text | null | undefined) {
  if (!node) return;
  if (Platform.OS === 'web') {
    // On web a ref is the DOM element itself.
    const element = node as unknown as HTMLElement;
    // Headings aren't focusable on their own; a button already reports 0.
    if (element.tabIndex < 0) element.tabIndex = -1;
    element.focus();
    return;
  }
  AccessibilityInfo.sendAccessibilityEvent(node, 'focus');
}

export default function EditTagsScreen() {
  const { theme } = useTheme();
  const { showToast } = useToast();
  const {
    closetMode,
    activeClosetId,
    activeClosetName,
    activeClosetLabels,
    isLoading,
    error,
    addOutfitLabel,
    removeOutfitLabel,
  } = useCloset();

  // Tags belong to the closet's owner. In stylist mode the active closet is
  // someone else's, so its tags are listed but can't be changed from here.
  const canEdit = closetMode === 'my-closet';

  const [draft, setDraft] = useState('');
  const [adding, setAdding] = useState(false);
  const [removing, setRemoving] = useState<string | null>(null);

  const listHeadingRef = useRef<Text>(null);
  const removeButtonRefs = useRef(new Map<string, View>());
  const [afterRemove, setAfterRemove] = useState<{ focusLabel: string | null; message: string } | null>(null);

  // The Remove button that was pressed unmounts with its row. Left alone,
  // keyboard focus on web drops to <body> and VoiceOver's cursor is left on
  // nothing, so the user loses their place in the list. Once the row is gone
  // this moves focus to the neighbouring row's Remove button (or to the list
  // heading when no row is left), and only then shows the toast - announcing
  // first would be cut off by the speech for the newly focused button.
  useEffect(() => {
    if (!afterRemove) return;
    const neighbour = afterRemove.focusLabel ? removeButtonRefs.current.get(afterRemove.focusLabel) : undefined;
    moveFocusTo(neighbour ?? listHeadingRef.current);
    showToast(afterRemove.message);
    setAfterRemove(null);
  }, [afterRemove, showToast]);

  // Add is never disabled, even with an empty field or a request in flight: a
  // disabled <button> drops keyboard focus on web. Problems are reported when
  // it is pressed instead.
  const handleAdd = async () => {
    if (adding) return;
    setAdding(true);
    try {
      const added = await addOutfitLabel(draft);
      setDraft('');
      showToast(`Added tag ${added}`);
    } catch (err) {
      showAlert("Couldn't add tag", getErrorMessage(err, 'Something went wrong. Please try again.'));
    } finally {
      setAdding(false);
    }
  };

  const handleRemove = (label: string) => {
    if (removing) return;
    // On web this becomes window.confirm, which drops the button labels - so
    // the question itself has to name the tag and say what happens.
    showAlert(
      'Remove tag',
      `Remove the tag "${label}"? Outfits that already use it keep it and still appear under All, but it will no longer be a filter or a choice for new outfits.`,
      [
        { text: 'Cancel', style: 'cancel' },
        {
          text: 'Remove',
          style: 'destructive',
          onPress: async () => {
            const index = activeClosetLabels.indexOf(label);
            const neighbour = activeClosetLabels[index + 1] ?? activeClosetLabels[index - 1] ?? null;
            setRemoving(label);
            try {
              await removeOutfitLabel(label);
              setAfterRemove({ focusLabel: neighbour, message: `Removed tag ${label}` });
            } catch (err) {
              showAlert("Couldn't remove tag", getErrorMessage(err, 'Something went wrong. Please try again.'));
            } finally {
              setRemoving(null);
            }
          },
        },
      ],
    );
  };

  const card = { backgroundColor: theme.surface, borderColor: theme.border };
  const count = activeClosetLabels.length;

  let content;
  if (isLoading) {
    content = (
      <View style={styles.centered}>
        <ActivityIndicator aria-label="Loading tags" />
      </View>
    );
  } else if (error) {
    content = (
      <View style={styles.centered}>
        <Text role="alert" style={[styles.message, { color: theme.danger }]}>{error}</Text>
      </View>
    );
  } else if (!activeClosetId) {
    content = (
      <View style={styles.centered}>
        <Text style={[styles.message, { color: theme.textSecondary }]}>
          {closetMode === 'stylist'
            ? "You aren't a stylist on any closets yet."
            : 'Create your closet on the Home tab to start using tags.'}
        </Text>
      </View>
    );
  } else {
    content = (
      <ScrollView style={styles.flex} contentContainerStyle={styles.container} keyboardShouldPersistTaps="handled">
        <Text style={[styles.intro, { color: theme.textSecondary }]}>
          {canEdit
            ? "Tags describe an outfit's vibe or occasion. You choose one when you create an outfit, and they are the filters on the Outfits tab."
            : `These are the tags for ${activeClosetName ?? 'this closet'}. Only the closet owner can add or remove tags. To edit your own tags, switch to My Closet on the Home tab.`}
        </Text>

        {canEdit && (
          <View style={[styles.card, card]}>
            <Text style={[styles.cardTitle, { color: theme.textPrimary }]} role="heading" aria-level={2}>
              Add a tag
            </Text>
            <Text style={[styles.fieldLabel, { color: theme.textPrimary }]}>New tag</Text>
            <TextInput
              value={draft}
              onChangeText={setDraft}
              onSubmitEditing={handleAdd}
              // Keeps focus in the field after Enter/Done so several tags can
              // be added in a row. Native reads submitBehavior;
              // react-native-web only knows blurOnSubmit.
              submitBehavior="submit"
              blurOnSubmit={false}
              returnKeyType="done"
              autoCapitalize="words"
              maxLength={MAX_OUTFIT_LABEL_LENGTH}
              placeholder="e.g. Vacation"
              placeholderTextColor={theme.textSecondary}
              style={[
                styles.textInput,
                { backgroundColor: theme.surfaceAlt, borderColor: theme.border, color: theme.textPrimary },
              ]}
              aria-label="New tag"
            />
            <Text style={[styles.hint, { color: theme.textSecondary }]}>
              Up to {MAX_OUTFIT_LABEL_LENGTH} characters.
            </Text>
            <Pressable
              onPress={handleAdd}
              role="button"
              aria-busy={adding}
              style={({ pressed }) => [styles.addButton, { backgroundColor: theme.accent }, pressed && styles.pressed]}
            >
              <Text style={[styles.addButtonText, { color: theme.onAccent }]}>Add tag</Text>
            </Pressable>
          </View>
        )}

        <View style={[styles.card, card]}>
          {/* Screen readers get "Tags, 10 tags" instead of a bare "(10)" - see ClosetHeader. */}
          <Text
            ref={listHeadingRef}
            style={[styles.cardTitle, { color: theme.textPrimary }]}
            role="heading"
            aria-level={2}
            aria-label={`Tags, ${count} ${count === 1 ? 'tag' : 'tags'}`}
          >
            Tags ({count})
          </Text>

          {count === 0 ? (
            <Text style={[styles.emptyText, { color: theme.textSecondary }]}>
              {canEdit ? 'No tags yet. Add one above.' : 'This closet has no tags yet.'}
            </Text>
          ) : (
            <View role="list">
              {activeClosetLabels.map((label, index) => (
                <View
                  key={label}
                  role="listitem"
                  style={[styles.tagRow, index > 0 && styles.tagRowDivider, { borderTopColor: theme.border }]}
                >
                  <Text style={[styles.tagText, { color: theme.textPrimary }]}>{label}</Text>
                  {canEdit && (
                    <Pressable
                      ref={node => {
                        if (node) removeButtonRefs.current.set(label, node);
                        else removeButtonRefs.current.delete(label);
                      }}
                      onPress={() => handleRemove(label)}
                      role="button"
                      aria-label={`Remove tag ${label}`}
                      aria-busy={removing === label}
                      style={({ pressed }) => [styles.removeButton, pressed && styles.pressed]}
                    >
                      <Text style={[styles.removeButtonText, { color: theme.danger }]}>Remove</Text>
                    </Pressable>
                  )}
                </View>
              ))}
            </View>
          )}
        </View>
      </ScrollView>
    );
  }

  return (
    <>
      <Stack.Screen options={{ title: 'Edit tags' }} />
      {content}
    </>
  );
}

