/** Control characters become spaces, whitespace runs collapse to one space, ends are trimmed. */
export function normalizeOutfitLabelName(raw: string): string {
  return raw.replace(/[\u0000-\u001F\u007F-\u009F]/g, ' ').replace(/\s+/g, ' ').trim();
}

/** Comparison key: two names with the same key are the same tag ("Work" = " work"). */
export function outfitLabelKey(name: string): string {
  return normalizeOutfitLabelName(name).toLowerCase();
}

export type OutfitLabelCheck = { ok: true; name: string } | { ok: false; message: string };

/** Client-side check before addClosetOutfitLabel; the database enforces the same rules. */
export function checkNewOutfitLabel(raw: string, existing: readonly ClosetOutfitLabel[]): OutfitLabelCheck;

