```ts
type ClosetOutfitLabelRow = Pick<Tables<'closet_outfit_labels'>, 'id' | 'closet_id' | 'name'>;
const LABEL_SELECT = 'id, closet_id, name';

export async function getClosetOutfitLabels(closetId: string): Promise<ClosetOutfitLabel[]> {
  const { data, error } = await supabase
    .from('closet_outfit_labels')
    .select(LABEL_SELECT)
    .eq('closet_id', closetId)
    .order('sort_order', { ascending: true })
    .order('created_at', { ascending: true })
    .order('name', { ascending: true })
    .returns<ClosetOutfitLabelRow[]>();
  if (error) throw error;
  return data;
}

export async function addClosetOutfitLabel(closetId: string, name: string): Promise<ClosetOutfitLabel> {
  const { data, error } = await supabase
    .from('closet_outfit_labels')
    .insert({ closet_id: closetId, name })
    .select(LABEL_SELECT)
    .returns<ClosetOutfitLabelRow[]>()
    .single();
  if (error) {
    if (error.code === '23505') throw new DuplicateOutfitLabelError(name);
    if (error.code === '42501') throw new Error('Only the closet owner can edit its tags.');
    if (error.code === '23514') {
      throw new Error(`Tags must be 1 to ${MAX_OUTFIT_LABEL_LENGTH} characters, with no line breaks or doubled spaces.`);
    }
    throw error; // includes the trigger's 'A closet can have at most 50 tags'
  }
  return data;
}

export async function removeClosetOutfitLabel(label: ClosetOutfitLabel): Promise<void> {
  const { data, error } = await supabase
    .from('closet_outfit_labels').delete().eq('id', label.id).select('id').maybeSingle();
  if (error) throw error;
  if (data) return;
  // Zero rows deleted is either "already removed on another device" (the end
  // state the caller wanted) or "RLS hid it from the delete" (not the owner).
  // A follow-up read tells the two apart.
  const { data: stillThere, error: checkError } = await supabase
    .from('closet_outfit_labels').select('id').eq('id', label.id).maybeSingle();
  if (checkError) throw checkError;
  if (stillThere) throw new Error('Only the closet owner can edit its tags.');
}
```

The client sends only closet_id and name; id, sort_order (1000 = after the starter tags) and created_at come from column defaults. Display order is (sort_order, created_at, name).

